weighted-fair-queuing.pseudocode:
class WFQ:
    def __init__(self, weights):
        self.w = weights  # 플로우별 가중치
        self.last_f = {f: 0.0 for f in weights}
        self.heap = []  # (가상 종료시간, 순번, 패킷)
        self.seq = 0

    def enqueue(self, flow, pkt, vtime):
        # vtime: 현재 시스템 가상시간 V(t), GPS로 계산
        start = max(self.last_f[flow], vtime)
        finish = start + pkt.length / self.w[flow]
        self.last_f[flow] = finish
        heappush(self.heap, (finish, self.seq, pkt))
        self.seq += 1

    def dequeue(self):
        if not self.heap:
            return None
        finish, _, pkt = heappop(self.heap)
        return pkt  # 가상 종료시간 최소부터 전송

weighted-round-robin.pseudocode:
def wrr(queues, weights, send):
    # queues[i]: FIFO 큐, weights[i]: 라운드당 패킷 수
    while any(queues):
        for q, w in zip(queues, weights):
            for _ in range(w):  # 가중치만큼 연속 송출
                if not q:
                    break  # 비면 다음 큐로
                send(q.popleft())
# 예: 가중치 3·2·1 → A A A B B C A A B B C ...

